abd4-fae90c3a9e4e/WEB_OldElk_FOH_Hero.png?format=2500w","u":"https://www.oldelk.com/folds-of-honor-american-whiskey","pr":"Old Elk","mk":"5df93c1c-7abe-4de0-b7d5-dad5b7aa9516"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');
